  const st = () => B().state || {}, cat = () => B().cat, cards = () => st().cards || [], packs = () => st().packs || {}, topSet = () => new Set(st().top || []), lockSet = () => new Set(st().lock || []);
  const opts = (c, extra) => Object.assign({ lock: lockSet().has(c.uid), top: topSet().has(c.uid) }, extra || {});
